const allCrafts=[{name:"Terracotta Pottery (Baked Earth Art)",icon:"🏺",district:"Gorakhpur & Bankura",category:"pottery",tags:["GI Tagged","Clay Art","Handicrafts"],description:"Ancient 5,000-year-old clay craft tradition featuring Bankura horses, Gorakhpur elephants, and Molela relief plaques.",history:"Dating back to the Indus Valley Civilization, terracotta represents sacred earth molded by human hands and kiln-fired to warm orange-red stoneware.",artisan:"Prajapati and Kumhar potters manually shaping riverbed silt on wooden wheels and open kilns.",detailsUrl:"../terracotta-pottery-explorer/index.html"},{name:"Channapatna Toys",icon:"🐘",district:"Channapatna, Karnataka",category:"toy",tags:["GI Tagged","Lacquerware","Wooden Toys"],description:"Karnataka's iconic lacquerware wooden toys — ivory wood turned on a bow lathe and finished with natural lac in warm, glossy colours.",history:"Handcrafted in the 'City of Toys' since the 18th century, when Tipu Sultan brought Persian lacquer artisans to Channapatna; GI-tagged in 2005.",artisan:"Channapatna toymakers who shape soft aale-mara wood on bow-powered lathes and seal it with molten natural lac resin.",detailsUrl:"../channapatna-toys-explorer/index.html"},{name:"Dokra Art",icon:"🪔",district:"Bastar, Dhenkanal & Bankura",category:"metal",tags:["Lost-Wax Casting","Tribal Art","Indus Valley Roots"],description:"India's ancient lost-wax metal casting craft — seamless bronze and brass figures of gods, beasts and ornaments by tribal artisans.",history:"Traced to the Indus Valley 'Dancing Girl' of Mohenjo-daro (c. 2500 BCE), Dokra keeps a 4,500-year-old casting lineage alive in Bastar, Dhenkanal and Bankura.",artisan:"Dokra Damar and Kamar tribal smiths who shape beeswax models, encase them in clay and pour molten bronze into the cavity left behind.",detailsUrl:"../dokra-art-explorer/index.html"},{name:"Kalighat Painting",icon:"🎨",district:"Kalighat, Kolkata",category:"folk-art",tags:["Bold Brushwork","Social Satire","19th Century Bengal"],description:"Bengal's iconic temple-ghat painting school — bold single-stroke brushwork on mill paper, fusing divine icons with biting social commentary.",history:"Emerged in 19th-century Calcutta near the Kalighat temple, where patua painters turned pilgrim souvenirs into India's first popular urban art school, lampooning baboos, priests and zamindars.",artisan:"Patua painters of the Kali ghat who drew each figure in one unbroken tapering stroke, now carried forward by revivalists like Santanu Chakraverty.",detailsUrl:"../kalighat-painting-showcase/index.html"},{name:"Manjusha Painting",icon:"🐍",district:"Bhagalpur, Bihar",category:"folk-art",tags:["GI Tagged","Snake Painting","Bihula–Bishari"],description:"Mythology-inspired temple-box folk art of the Anga region, painted for the Bishari Puja with swirling serpent motifs.",history:"A 7th-century folk-art tradition from Bhagalpur (Anga Mahajanapada), Manjusha paintings retell the Bihula–Bishari legend on temple-shaped bamboo, jute and paper caskets.",artisan:"Kumbhakar and Malakar community artists who paint bold outlines with bamboo kalams on gum-pasted cloth, keeping the Shravan Bishari Puja alive.",detailsUrl:"../manjusha-painting-explorer/index.html"},{name:"Chhau Dance Masks",icon:"🎭",district:"Purulia & Charida",category:"mask",tags:["UNESCO Listed","Paper-Mache","Folk Art"],description:"Vibrant hand-sculpted papier-mâché dance masks used in Purulia and Seraikela Chhau martial folk theater.",history:"Centuries-old folk performance mask art created by Sutradhar artisans depicting Ramayana, Mahabharata, and Puranic deities.",artisan:"Charida village artisans in Purulia crafting lightweight paper-mache shells embellished with peacock feathers and zari crowns.",detailsUrl:"../chhau-masks-explorer/index.html"},{name:"Bidriware Metal Inlay",icon:"✨",district:"Bidar, Karnataka",category:"metal",tags:["GI Tagged","Silver Inlay","Metalcraft"],description:"Iconic metal handicraft of Karnataka featuring pure silver wire inlay on a jet-black zinc alloy base.",history:"14th-century Bahmani Sultanate metalcraft developed in Bidar using unique nitrate-rich Bidar Fort soil for oxidation.",artisan:"Master Bidri engravers hammering pure silver wire into zinc-copper castings.",detailsUrl:"../bidriware-craftsmanship-explorer/index.html"},{name:"Bastar Iron Craft (Loha Shilp)",icon:"🔨",district:"Bastar & Kondagaon",category:"metal",tags:["GI Tagged","Wrought Iron","Tribal Art"],description:"Traditional hand-forged wrought iron craft by Bastar tribal artisans creating sleek figurines and oil lamps.",history:"Ancestral metal forging tradition practiced by Lohar artisans of Chhattisgarh using charcoal kilns and anvils without any welding.",artisan:"Kondagaon Lohar craftspersons manually beating scrap iron into tribal dancers, deer, and Dipa Stambha tree lamps.",detailsUrl:"../bastar-iron-craft-explorer/index.html"},{name:"Lucknow Chikankari",icon:"🪡",district:"Lucknow",category:"textile",tags:["GI Tagged","Embroidery"],description:"A delicate white-thread embroidery style done on fine fabrics like muslin, chiffon, and organza.",history:"Chikankari traces its roots to the Mughal era, with the word 'chikan' derived from a Persian term for fabric fashioned by embroidery. It flourished under Awadh's Nawabs and reached its artistic peak in Lucknow.",artisan:"Skilled chikan artisans, many of them women working from home, use techniques like 'bakhia', 'murri', and 'keel kangan' to create over 30 distinct stitch styles, often passed down through generations.",districtStory:"Lucknow remains the beating heart of chikankari, with entire neighbourhoods of artisan families dedicated to hand-embroidering sarees, kurtas, and dupattas for markets across India and abroad."},{name:"Moradabad Brassware",icon:"🏺",district:"Moradabad",category:"metal",tags:["GI Tagged","Metalwork"],description:"Intricately engraved brass, copper, and aluminium items known for ornamental and utilitarian craftsmanship.",history:"Moradabad has been a metalworking hub for centuries, earning the nickname 'Peetal Nagri' (Brass City) of India for its dominance in decorative and export-quality metal crafts.",artisan:"Artisans use two primary engraving techniques — 'Naqashi' (done on a tinned surface) and 'Khudai' (done on lac-coated unpolished brass) — to create vases, idols, trays, and contemporary bowls.",districtStory:"Moradabad exports brassware to countries around the world, making it one of India's most significant handicraft export centres, employing thousands of skilled metal artisans."},{name:"Bhadohi Carpets",icon:"🧶",district:"Bhadohi",category:"carpet",tags:["GI Tagged","Hand-knotted"],description:"Hand-knotted wool and silk carpets known worldwide for intricate designs and remarkable durability.",history:"Bhadohi's carpet-weaving tradition dates back centuries and the region is often referred to as the 'Carpet City' of India, supplying premium hand-knotted rugs to global markets.",artisan:"Weavers use traditional knotting techniques passed through generations, with a single large carpet sometimes taking several artisans many months of patient, meticulous work to complete.",districtStory:"Bhadohi, along with neighbouring Mirzapur, forms the largest hand-knotted carpet weaving belt in India, contributing significantly to the country's handicraft exports."},{name:"Firozabad Glassware",icon:"🔮",district:"Firozabad",category:"glass",tags:["GI Tagged","Glasswork"],description:"Decorative glass bangles, beads, and lighting pieces that showcase the region's centuries-old glassblowing tradition.",history:"Firozabad's glass industry is believed to have flourished under Mughal patronage, and the city has since become synonymous with glass bangles across India.",artisan:"Glassblowers work near furnaces at extreme temperatures, shaping molten glass into bangles, chandeliers, and decorative pieces with techniques refined over many generations.",districtStory:"Firozabad is often called the 'Glass City' of India, and its bangle industry alone supports a vast network of artisan families and small workshops."},{name:"Saharanpur Wood Carving",icon:"🪵",district:"Saharanpur",category:"wood",tags:["GI Tagged","Woodcraft"],description:"Ornamental wooden furniture and decorative objects carved with intricate floral and geometric designs.",history:"Saharanpur's woodcraft tradition is believed to have been influenced by Kashmiri settlers, blending Kashmiri carving patterns with local craftsmanship on teak, sheesham, and deodar wood.",artisan:"Master carvers, known locally for their inlay and jali work, spend years perfecting the fine detailing seen on furniture, screens, and decorative panels.",districtStory:"Saharanpur's wood carving industry contributes significantly to India's handicraft exports, with pieces finding their way into homes and galleries worldwide."},{name:"Banarasi Silk Saree",icon:"🧵",district:"Varanasi",category:"textile",tags:["GI Tagged","Silk"],description:"Luxurious silk sarees woven with intricate gold and silver zari work, considered among India's finest textiles.",history:"Banarasi silk weaving is thought to have flourished during the Mughal era, when Persian motifs blended with Indian silk weaving traditions to create the distinctive Banarasi style.",artisan:"Weaver families in Varanasi work on traditional handlooms, sometimes taking weeks to complete a single saree with elaborate brocade patterns and zari borders.",districtStory:"Varanasi holds the highest number of GI-tagged products of any Indian city, with Banarasi silk remaining its most globally recognised textile export."},{name:"Varanasi Zardozi",icon:"✨",district:"Varanasi",category:"textile",tags:["Embroidery","Metallic Thread"],description:"Opulent gold and silver thread embroidery used to create lavish, intricate designs on fabric.",history:"Zardozi embroidery has roots in royal Mughal courts, where artisans embellished garments and tapestries for royalty using real gold and silver threads.",artisan:"Zardozi artisans use fine metallic threads, sequins, and beads, stitching elaborate patterns onto silk and velvet, often for bridal wear and ceremonial garments.",districtStory:"Varanasi's zardozi workshops continue a centuries-old tradition, with many artisan families still practising skills inherited from their ancestors."},{name:"Khurja Pottery",icon:"🏺",district:"Bulandshahr",category:"glass",tags:["GI Tagged","Ceramics"],description:"Refined ceramic pottery known for its distinctive blue, green, and brown glazes, often called India's ceramics capital craft.",history:"Khurja's pottery tradition developed with influences from Persian ceramic styles, evolving over centuries into a distinctly Indian glazed pottery art form.",artisan:"Potters shape refined clay on traditional wheels before hand-painting and glazing each piece, a process requiring both technical skill and artistic patience.",districtStory:"Khurja town, near Bulandshahr, is widely known as the 'Ceramics Capital of India', with generations of potter families keeping the tradition alive."},{name:"Kannauj Attar",icon:"🌸",district:"Kannauj",category:"textile",tags:["GI Tagged","Perfumery"],description:"Traditional natural perfumes distilled from flowers, herbs, and spices using centuries-old techniques.",history:"Kannauj's perfumery tradition is believed to be centuries old, earning the town the title 'Perfume Capital of India' for its natural attar-making heritage.",artisan:"Perfumers use the traditional 'deg-bhapka' distillation method, capturing floral essences in sandalwood oil over long, carefully monitored processes.",districtStory:"Kannauj remains home to hundreds of small-scale attar distilleries, exporting natural perfumes to markets across India and the Middle East."},{name:"Agra Stone Inlay",icon:"🗿",district:"Agra",category:"wood",tags:["Stonecraft","Pietra Dura"],description:"Fine marble stone-carving and inlay work inspired by the decorative techniques seen on the Taj Mahal.",history:"Agra's stone inlay craft, known as 'Pietra Dura', developed alongside the construction of Mughal monuments, with artisan families continuing techniques used on the Taj Mahal itself.",artisan:"Craftsmen embed semi-precious stones into white marble to create intricate floral patterns, a painstaking process requiring extreme precision.",districtStory:"Many of today's Agra stone-inlay artisans trace their lineage directly back to craftsmen who worked on the Taj Mahal centuries ago."},{name:"Mainpuri Tarkashi",icon:"🪞",district:"Mainpuri",category:"wood",tags:["Wire Inlay","Woodwork"],description:"A unique craft of inlaying fine brass wire into wooden furniture and decorative boxes.",history:"Tarkashi, meaning wire craft, developed in Mainpuri as artisans began embedding thin brass wires into wood to create striking geometric and floral patterns.",artisan:"Artisans carve fine grooves into wood before carefully hammering brass wire into place, creating a shimmering contrast against the dark wood surface.",districtStory:"Mainpuri remains one of the few places in India where this delicate wire-inlay woodcraft tradition is still actively practised and taught."},{name:"Varanasi Wooden Toys",icon:"🧸",district:"Varanasi",category:"wood",tags:["Toys","Lacquerware"],description:"Brightly lacquered wooden toys and figurines handcrafted using traditional turning and painting techniques.",history:"Varanasi's wooden toy-making tradition has been passed down for generations, with artisans crafting figurines, spinning tops, and decorative pieces for both play and display.",artisan:"Craftsmen shape soft wood on manual lathes before hand-painting each toy with vivid natural and synthetic colours in traditional patterns.",districtStory:"Varanasi's toy-making clusters continue to supply colourful wooden toys to markets across northern India, keeping a centuries-old craft alive."},{name:"Meerut Scissors & Tools",icon:"✂️",district:"Meerut",category:"metal",tags:["GI Tagged","Tool-making"],description:"Precision-made scissors and cutting tools known for their sharpness and durability.",history:"Meerut's metal tool-making tradition developed over generations, establishing the city as a major centre for scissors and cutlery production in North India.",artisan:"Skilled metalworkers forge, sharpen, and finish each tool by hand, combining traditional blacksmithing techniques with modern precision finishing.",districtStory:"Meerut remains one of India's largest hubs for scissors and cutting-tool manufacturing, exporting to both domestic and international markets."},{name:"Kanpur Leathercraft",icon:"👞",district:"Kanpur",category:"textile",tags:["Leather","Footwear"],description:"High-quality leather goods including footwear, saddles, and harnesses known for durability and fine finishing.",history:"Kanpur's leather industry grew rapidly during the colonial era, evolving into one of India's most significant leather manufacturing and export hubs.",artisan:"Leather artisans in Kanpur combine traditional tanning and stitching methods with modern techniques to produce footwear and goods valued for their craftsmanship.",districtStory:"Kanpur is often referred to as the 'Leather City' of India, home to hundreds of tanneries and workshops supplying products worldwide."},{name:"Farrukhabad Hand-Block Printing",icon:"🖨️",district:"Farrukhabad",category:"textile",tags:["Block Printing","Textile Art"],description:"Vibrant hand-block printed textiles known for bold colours and distinctive traditional patterns.",history:"Farrukhabad's block-printing tradition developed as a distinct regional style, with hand-carved wooden blocks used to stamp intricate patterns onto fabric.",artisan:"Printers carve detailed wooden blocks before hand-stamping fabric in layered colours, a process requiring precise alignment and a steady hand.",districtStory:"Farrukhabad's textile printing clusters continue to produce fabrics that are popular across India for their distinctive and vibrant regional patterns."},{name:"Agra Durries",icon:"🧵",district:"Agra",category:"carpet",tags:["Flat-weave","Cotton Rugs"],description:"Flat-woven cotton rugs known for bright geometric patterns and everyday comfort.",history:"Durrie weaving in Agra developed as a practical craft, producing sturdy, colourful floor coverings suited to daily household use across North India.",artisan:"Weavers use traditional handlooms to interlace cotton threads into bold geometric patterns, creating durable rugs prized for both function and design.",districtStory:"Agra's durrie-weaving communities continue producing these versatile rugs, popular in both traditional homes and modern interior design."}],districtLabels={};allCrafts.forEach(a=>{districtLabels[a.district]=a.district});let activeDistrict="all",activeCategory="all",searchQuery="",selectedCraftName=null;const craftGrid=document.getElementById("craftGrid"),noResults=document.getElementById("noResults"),resultsCount=document.getElementById("resultsCount"),searchInput=document.getElementById("searchInput"),districtList=document.getElementById("districtList"),categoryList=document.getElementById("categoryList"),totalCraftsStat=document.getElementById("totalCraftsStat"),totalDistrictsStat=document.getElementById("totalDistrictsStat"),detailEmpty=document.getElementById("detailEmpty"),detailContent=document.getElementById("detailContent"),detailCloseBtn=document.getElementById("detailCloseBtn"),detailIcon=document.getElementById("detailIcon"),detailDistrictTag=document.getElementById("detailDistrictTag"),detailTitle=document.getElementById("detailTitle"),detailDescription=document.getElementById("detailDescription"),detailHistory=document.getElementById("detailHistory"),detailArtisan=document.getElementById("detailArtisan"),detailDistrictStory=document.getElementById("detailDistrictStory");function buildDistrictButtons(){[...new Set(allCrafts.map(a=>a.district))].sort().forEach(a=>{const t=document.createElement("button");t.className="district-btn",t.dataset.district=a,t.innerHTML=`<span class="district-name">${a}</span>`,districtList.appendChild(t)})}function renderCrafts(){const a=allCrafts.filter(a=>{const t="all"===activeDistrict||a.district===activeDistrict,e="all"===activeCategory||a.category===activeCategory,i=""===searchQuery||a.name.toLowerCase().includes(searchQuery)||a.district.toLowerCase().includes(searchQuery)||a.description.toLowerCase().includes(searchQuery);return t&&e&&i});if(resultsCount.textContent=`Showing ${a.length} craft${1!==a.length?"s":""}`,0===a.length)return craftGrid.innerHTML="",void noResults.classList.remove("hidden");noResults.classList.add("hidden"),craftGrid.innerHTML="",a.forEach(a=>{const t=document.createElement("div");t.className="craft-card"+(a.name===selectedCraftName?" selected":""),t.innerHTML=`\n      <span class="craft-card-icon">${a.icon}</span>\n      <span class="craft-card-district">${a.district}</span>\n      <h3 class="craft-card-name">${a.name}</h3>\n      <p class="craft-card-desc">${a.description}</p>\n      <div class="craft-card-tags">\n        ${a.tags.map(a=>`<span class="craft-tag">${a}</span>`).join("")}\n      </div>\n    `,t.addEventListener("click",()=>showDetail(a)),craftGrid.appendChild(t)})}function showDetail(a){selectedCraftName=a.name,detailIcon.textContent=a.icon,detailDistrictTag.textContent=a.district,detailTitle.textContent=a.name,detailDescription.textContent=a.description,detailHistory.textContent=a.history,detailArtisan.textContent=a.artisan,detailDistrictStory.textContent=a.districtStory,detailEmpty.classList.add("hidden"),detailContent.classList.remove("hidden"),renderCrafts()}function closeDetail(){selectedCraftName=null,detailContent.classList.add("hidden"),detailEmpty.classList.remove("hidden"),renderCrafts()}function updateStats(){totalCraftsStat.textContent=allCrafts.length,totalDistrictsStat.textContent=new Set(allCrafts.map(a=>a.district)).size}detailCloseBtn.addEventListener("click",closeDetail),districtList.addEventListener("click",a=>{const t=a.target.closest(".district-btn");t&&(districtList.querySelectorAll(".district-btn").forEach(a=>a.classList.remove("active")),t.classList.add("active"),activeDistrict=t.dataset.district,renderCrafts())}),categoryList.addEventListener("click",a=>{const t=a.target.closest(".category-btn");t&&(categoryList.querySelectorAll(".category-btn").forEach(a=>a.classList.remove("active")),t.classList.add("active"),activeCategory=t.dataset.category,renderCrafts())}),searchInput.addEventListener("input",a=>{searchQuery=a.target.value.trim().toLowerCase(),renderCrafts()}),buildDistrictButtons(),updateStats(),renderCrafts();